mod actions {
use crate::ice_and_fire_engine::state::BUILD_COST;
use crate::ice_and_fire_engine::{Bits, Command, State, HQ, SIZE};
use crate::ice_and_fire_tactics::chain::chain_to;
use crate::ice_and_fire_tactics::cut::cuts;
pub const MACRO_CUTS: usize = 4;
pub const CUT_LENGTH: usize = 5;
pub enum Action {
One(Command),
Many(Vec<Command>),
}
impl Action {
pub fn commands(&self) -> &[Command] {
match self {
Action::One(command) => std::slice::from_ref(command),
Action::Many(commands) => commands,
}
}
}
pub fn xy(cell: usize) -> (u8, u8) {
((cell % SIZE) as u8, (cell / SIZE) as u8)
}
pub fn generate(state: &State, out: &mut Vec<Action>) {
out.clear();
if state.outcome().is_some() {
return;
}
let me = state.to_act();
let max = state.league().max_level();
let mut enter = [Bits::EMPTY; 4];
for level in 1..=max {
enter[usize::from(level)] = state.enterable(me, level);
}
for from in state.movable_units().iter() {
let Some((id, level)) = state.unit_at(from) else {
continue;
};
let steps = Bits::cell(from).neighbours() & enter[usize::from(level)];
for to in steps.iter() {
let (x, y) = xy(to);
out.push(Action::One(Command::Move { id, x, y }));
}
}
let gold = state.gold(me);
let near = state.near_active(me);
for level in 1..=max {
let cost = 10 * i64::from(level);
if gold < cost {
break;
}
let mut cells = near & enter[usize::from(level)];
for lower in 1..level {
cells = cells.and_not(enter[usize::from(lower)]);
}
for cell in cells.iter() {
let (x, y) = xy(cell);
out.push(Action::One(Command::Train { level, x, y }));
}
}
if gold >= BUILD_COST {
let free = state.owned(me) & near & state.empty_cells();
if state.league().allows_mines() {
for cell in (free & state.map().spots).iter() {
let (x, y) = xy(cell);
out.push(Action::One(Command::BuildMine { x, y }));
}
}
if state.league().allows_towers() {
let border = state.map().valid.and_not(state.owned(me)).neighbours();
let cells = (free & border).and_not(state.map().spots);
for cell in cells.iter() {
let (x, y) = xy(cell);
out.push(Action::One(Command::BuildTower { x, y }));
}
}
}
for cut in cuts(state, CUT_LENGTH, gold, MACRO_CUTS) {
if cut.commands.len() > 1 {
out.push(Action::Many(cut.commands));
}
}
if let Some(chain) = chain_to(state, HQ[1 - me], gold) {
if chain.commands.len() > 1 {
out.push(Action::Many(chain.commands));
}
}
}
}
mod eval {
use crate::ice_and_fire_engine::State;
use crate::ice_and_fire_opening::solo::severed;
use crate::ice_and_fire_tactics::eval::evaluate;
const SHAPE: i64 = 2;
fn weakness(state: &State, seat: usize) -> i64 {
let cut = severed(state, seat);
let mut joints = 0;
let mut most = 0;
for cell in state.active(seat).iter() {
if cut[cell] > 0 {
joints += 1;
most = most.max(cut[cell]);
}
}
joints + most
}
pub fn shape(state: &State, seat: usize) -> i64 {
SHAPE * (weakness(state, 1 - seat) - weakness(state, seat))
}
fn debt(state: &State, seat: usize) -> i64 {
if state.gold(seat) + state.income(seat) >= 0 {
return 0;
}
(state.units(seat) & state.active(seat))
.iter()
.filter_map(|cell| state.unit_level(cell))
.map(|level| 10 * i64::from(level))
.sum()
}
pub const LEVEL2_DISCOUNT: i64 = 15;
fn twos(state: &State, seat: usize) -> i64 {
(state.units(seat) & state.active(seat))
.iter()
.filter(|&cell| state.unit_level(cell) == Some(2))
.count() as i64
}
pub fn eval(state: &State, seat: usize) -> i64 {
let score = evaluate(state, seat);
if state.outcome().is_some() {
return score;
}
score - 2 * debt(state, seat)
+ 2 * debt(state, 1 - seat)
+ shape(state, seat)
+ LEVEL2_DISCOUNT * (twos(state, 1 - seat) - twos(state, seat))
}
}
mod search {
use std::collections::hash_map::DefaultHasher;
use std::collections::HashMap;
use std::hash::BuildHasherDefault;
use std::time::Instant;
use crate::ice_and_fire_engine::{Command, Outcome, State, HQ};
use crate::ice_and_fire_opening::planned::Planned;
use crate::ice_and_fire_policy::greedy_turn;
use crate::ice_and_fire_tactics::chain::chain_to;
use crate::ice_and_fire_tactics::cut::cuts;
use crate::ice_and_fire_tactics::eval::WIN;
use crate::actions::{generate, xy, Action, CUT_LENGTH};
use crate::eval::eval;
const MEMORY_CAP: usize = 8;
const REPLY_CUTS: usize = 3;
const MAX_CLIMBS: usize = 32;
const REPLY_EVALS: u64 = 300;
#[derive(Clone, Copy)]
pub struct Limit {
pub soft: Option<Instant>,
pub hard: Option<Instant>,
pub max_evals: u64,
}
#[derive(Default)]
pub struct Thought {
pub commands: Vec<Command>,
pub climbs: usize,
pub evals: u64,
pub memory: usize,
pub plans: usize,
}
struct Reply {
commands: Vec<Command>,
damage: i64,
}
struct Plan {
commands: Vec<Command>,
end: State,
first: Option<u64>,
}
type Gains = HashMap<u64, i64, BuildHasherDefault<DefaultHasher>>;
struct Search {
me: usize,
limit: Limit,
evals: u64,
hints: Gains,
}
fn apply_all(state: &mut State, commands: &[Command]) -> bool {
commands.iter().all(|&command| state.apply(command))
}
fn key(commands: &[Command]) -> u64 {
let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
for command in commands {
let (kind, a, b, c) = match *command {
Command::Move { id, x, y } => (1, u64::from(id), x, y),
Command::Train { level, x, y } => (2, u64::from(level), x, y),
Command::BuildMine { x, y } => (3, 0, x, y),
Command::BuildTower { x, y } => (4, 0, x, y),
Command::Wait => (5, 0, 0, 0),
};
let word = kind | a << 8 | u64::from(b) << 40 | u64::from(c) << 48;
hash = (hash ^ word).wrapping_mul(0x0100_0000_01b3);
}
hash
}
fn after_reply(end: &State, reply: &[Command]) -> State {
let mut next = end.clone();
next.end_turn();
for &command in reply {
next.apply(command);
}
next.end_turn();
next
}
fn lethal(state: &State) -> Option<Vec<Command>> {
let me = state.to_act();
let target = HQ[1 - me];
let wins = |trial: &State| trial.outcome() == Some(Outcome::Win(me));
for cell in state.movable_units().iter() {
if state.map().distance(cell, target) != 1 {
continue;
}
let Some((id, _)) = state.unit_at(cell) else {
continue;
};
let (x, y) = xy(target);
let command = Command::Move { id, x, y };
let mut trial = state.clone();
if trial.apply(command) && wins(&trial) {
return Some(vec![command]);
}
}
let chain = chain_to(state, target, state.gold(me))?;
let mut trial = state.clone();
(apply_all(&mut trial, &chain.commands) && wins(&trial)).then_some(chain.commands)
}
impl Search {
fn spent(&self) -> bool {
self.evals >= self.limit.max_evals
|| self.limit.soft.is_some_and(|t| Instant::now() >= t)
}
fn score(&mut self, end: &State, memory: &[Reply], bound: i64) -> i64 {
self.evals += 1;
self.rate(end, memory, bound)
}
fn rate(&self, end: &State, memory: &[Reply], bound: i64) -> i64 {
if end.outcome() == Some(Outcome::Win(self.me)) {
return WIN;
}
if memory.is_empty() {
return eval(end, self.me);
}
let mut worst = i64::MAX;
for reply in memory {
worst = worst.min(eval(&after_reply(end, &reply.commands), self.me));
if worst <= bound {
break;
}
}
worst
}
#[allow(clippy::too_many_arguments)]
fn pass(
&mut self,
cur: &State,
cur_score: i64,
actions: &[Action],
order: &[(i64, usize)],
done: &mut [bool],
memory: &[Reply],
gains: &mut Gains,
lazy: bool,
) -> (Option<(usize, State, i64)>, bool) {
let mut best = None;
let mut best_score = cur_score;
for &(old, index) in order {
if done[index] {
continue;
}
if lazy && old != i64::MAX && old <= best_score - cur_score {
return (best, true);
}
if self.spent() {
return (best, false);
}
done[index] = true;
let commands = actions[index].commands();
let mut next = cur.clone();
if !apply_all(&mut next, commands) {
gains.insert(key(commands), i64::MIN / 4);
continue;
}
let score = self.score(&next, memory, best_score);
gains.insert(key(commands), score - cur_score);
if score > best_score {
best_score = score;
best = Some((index, next, score));
}
}
(best, false)
}
fn climb(&mut self, root: &State, memory: &[Reply], banned: &[u64]) -> Plan {
let mut first = None;
let mut cur = root.clone();
let mut commands = Vec::new();
let mut cur_score = self.score(&cur, memory, i64::MIN);
let mut gains = Gains::default();
let mut actions = Vec::new();
let mut order = Vec::new();
while cur.outcome().is_none() && !self.spent() {
generate(&cur, &mut actions);
order.clear();
for (index, action) in actions.iter().enumerate() {
let k = key(action.commands());
let old = gains.get(&k).or(self.hints.get(&k)).copied();
order.push((old.unwrap_or(i64::MAX), index));
}
order.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
let mut done = vec![false; actions.len()];
if commands.is_empty() {
for (index, action) in actions.iter().enumerate() {
done[index] = banned.contains(&key(action.commands()));
}
}
let mut best = None;
for lazy in [true, false] {
let (found, skipped) = self.pass(
&cur, cur_score, &actions, &order, &mut done, memory, &mut gains, lazy,
);
best = found;
if best.is_some() || !skipped {
break;
}
}
let Some((index, next, score)) = best else {
break;
};
if commands.is_empty() {
first = Some(key(actions[index].commands()));
}
commands.extend_from_slice(actions[index].commands());
cur = next;
cur_score = score;
}
for (k, gain) in gains {
let hint = self.hints.entry(k).or_insert(gain);
*hint = (*hint).max(gain);
}
Plan {
commands,
end: cur,
first,
}
}
fn replies(&self, end: &State) -> Vec<Vec<Command>> {
let mut next = end.clone();
next.end_turn();
let mut out = Vec::new();
if next.outcome().is_some() {
return out;
}
let opponent = next.to_act();
let gold = next.gold(opponent);
if let Some(chain) = chain_to(&next, HQ[self.me], gold) {
out.push(chain.commands);
}
for cut in cuts(&next, CUT_LENGTH, gold, REPLY_CUTS) {
out.push(cut.commands);
}
let mut greedy = Vec::new();
greedy_turn(&next, &mut greedy);
out.push(greedy);
let mut theirs = Search {
me: opponent,
limit: Limit {
max_evals: REPLY_EVALS,
..self.limit
},
evals: 0,
hints: Gains::default(),
};
out.push(theirs.climb(&next, &[], &[]).commands);
out.retain(|commands| !commands.is_empty());
out
}
fn remember(&self, end: &State, memory: &mut Vec<Reply>) -> bool {
let before: Vec<_> = memory.iter().map(|r| r.commands.clone()).collect();
for commands in self.replies(end) {
if memory.iter().any(|r| r.commands == commands) {
continue;
}
let damage = eval(&after_reply(end, &commands), self.me);
memory.push(Reply { commands, damage });
}
memory.sort_by_key(|reply| reply.damage);
memory.truncate(MEMORY_CAP);
memory.iter().map(|r| &r.commands).ne(&before)
}
}
pub fn think(state: &State, limit: Limit, opening: &mut Planned) -> Thought {
let me = state.to_act();
let mut thought = Thought::default();
if state.outcome().is_some() {
return thought;
}
if let Some(commands) = lethal(state) {
thought.commands = commands;
return thought;
}
if opening.playing(state) {
let at = |share: f64| match (limit.soft, limit.hard) {
(Some(soft), Some(hard)) => Some(soft + (hard - soft).mul_f64(share)),
_ => None,
};
thought.commands = opening.turn(state, at(0.4));
return thought;
}
let mut search = Search {
me,
limit,
evals: 0,
hints: Gains::default(),
};
let mut memory = Vec::new();
let mut plans: Vec<Plan> = Vec::new();
let mut banned = Vec::new();
while thought.climbs < MAX_CLIMBS && (plans.is_empty() || !search.spent()) {
let plan = search.climb(state, &memory, &banned);
thought.climbs += 1;
let same = plans.iter().any(|p| p.commands == plan.commands);
let first = plan.first;
let stop = search.spent();
let more = !stop && !same && search.remember(&plan.end, &mut memory);
if !same {
plans.push(plan);
}
if stop {
break;
}
if !more {
match first {
Some(first) => banned.push(first),
None => break,
}
}
}
thought.evals = search.evals;
thought.memory = memory.len();
thought.plans = plans.len();
let mut best: Option<(i64, usize)> = None;
for (index, plan) in plans.iter().enumerate().rev() {
if best.is_some() && limit.hard.is_some_and(|t| Instant::now() >= t) {
break;
}
let score = search.rate(&plan.end, &memory, i64::MIN);
if best.is_none_or(|(top, _)| score > top) {
best = Some((score, index));
}
}
if let Some((_, index)) = best {
let mut scratch = state.clone();
for &command in &plans[index].commands {
if scratch.apply(command) {
thought.commands.push(command);
}
}
}
thought
}
}
mod session {
use std::io::{BufRead, Write};
use std::time::Instant;
use crate::ice_and_fire_engine::{answer_line, League, State};
use crate::ice_and_fire_opening::planned::Planned;
use crate::ice_and_fire_policy::io::turns;
use crate::search::{think, Limit};
pub fn play(
limit: &dyn Fn(Instant, u32) -> Limit,
mut opening: Planned,
input: impl BufRead,
output: impl Write,
) -> Result<(), String> {
turns(
input,
output,
|initial, text, turn, start| match State::read(initial, text, League::Bronze, turn) {
Ok(state) => {
let thought = think(&state, limit(start, turn), &mut opening);
eprintln!(
"turn {turn}: climbs {} tries {} memory {} {:?}",
thought.climbs,
thought.evals,
thought.memory,
start.elapsed()
);
answer_line(&thought.commands)
}
Err(err) => {
eprintln!("plan: cannot read the input: {err}");
"WAIT".to_string()
}
},
)
}
}
use std::io;
use std::time::{Duration, Instant};
use crate::ice_and_fire_opening::econ::Params;
use crate::ice_and_fire_opening::planned::{Planned, Planner};
use crate::ice_and_fire_opening::solo::{self, Objective};
use crate::search::Limit;
const BUDGET_MS: f64 = 40.0;
const FIRST_BUDGET_MS: f64 = 800.0;
const SOFT_SHARE: f64 = 0.6;
fn limit(start: Instant, turn: u32) -> Limit {
if let Some(max_evals) = std::env::var("CG_FIXED_ITERS")
.ok()
.and_then(|n| n.trim().parse().ok())
.filter(|&n| n > 0)
{
return Limit {
soft: None,
hard: None,
max_evals,
};
}
let scale = crate::cg_core::time::time_scale().min(100.0);
let ms = if turn == 1 {
FIRST_BUDGET_MS
} else {
BUDGET_MS
};
let budget = Duration::from_secs_f64(ms / 1000.0 * scale);
Limit {
soft: Some(start + budget.mul_f64(SOFT_SHARE)),
hard: Some(start + budget),
max_evals: u64::MAX,
}
}
const OPENING_TURNS: usize = 7;
const OBJECTIVE: Objective = Objective {
cells: 4,
income: 3,
gold: 1,
cut: 2,
joints: 2,
tips: 2,
reach: 6,
voronoi: 1,
};
fn opening() -> Planned {
opening_of(64)
}
fn opening_of(width: usize) -> Planned {
let planner = Planner::Solo {
turns: OPENING_TURNS,
width,
objective: OBJECTIVE,
};
Planned::new(planner, solo::SETS.to_vec(), Params::V003)
}
fn main() {
let stdin = io::stdin();
let stdout = io::stdout();
if let Err(err) = session::play(&limit, opening(), stdin.lock(), stdout.lock()) {
eprintln!("plan: {err}");
std::process::exit(1);
}
}
